```java
import java.util.Scanner;
import java.util.List;
import java.util.ArrayList;

public class Main {
    static int L, C, P;
    static int[][] grid;
    static int maxWhites = 0;
    static List<int[]> candidates = new ArrayList<>();
    static int numCandidates = 0;

    static final int[] dr = {-1, 1, 0, 0};
    static final int[] dc = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        L = sc.nextInt();
        C = sc.nextInt();
        P = sc.nextInt();

        grid = new int[L][C]; // 0: vazio, 1: preta, 2: branca

        for (int i = 0; i < P; i++) {
            int r = sc.nextInt() - 1;
            int c = sc.nextInt() - 1;
            grid[r][c] = 1;
        }

        // Encontrar todas as casas que são adjacentes a pelo menos uma peça preta e estão vazias
        for (int r = 0; r < L; r++) {
            for (int c = 0; c < C; c++) {
                if (grid[r][c] == 0) {
                    boolean hasBlackNeighbor = false;
                    for (int d = 0; d < 4; d++) {
                        int nr = r + dr[d];
                        int nc = c + dc[d];
                        if (nr >= 0 && nr < L && nc >= 0 && nc < C) {
                            if (grid[nr][nc] == 1) {
                                hasBlackNeighbor = true;
                                break;
                            }
                        }
                    }
                    if (hasBlackNeighbor) {
                        candidates.add(new int[]{r, c});
                    }
                }
            }
        }

        numCandidates = candidates.size();
        backtrack(0, 0);

        System.out.println(maxWhites);
    }

    static void backtrack(int idx, int currentWhites) {
        if (currentWhites + (numCandidates - idx) <= maxWhites) {
            return;
        }

        if (idx == numCandidates) {
            if (currentWhites > maxWhites) {
                maxWhites = currentWhites;
            }
            return;
        }

        int[] cell = candidates.get(idx);
        int r = cell[0];
        int c = cell[1];

        // Opção 1: tentar colocar uma peça branca
        boolean canPlace = true;
        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d];
            int nc = c + dc[d];
            if (nr >= 0 && nr < L && nc >= 0 && nc < C) {
                if (grid[nr][nc] == 2) {
                    canPlace = false;
                    break;
                }
            }
        }

        if (canPlace) {
            grid[r][c] = 2;
            backtrack(idx + 1, currentWhites + 1);
            grid[r][c] = 0;
        }

        // Opção 2: não colocar peça branca
        backtrack(idx + 1, currentWhites);
    }
}
```

